// TestResume_FullFetchEvenWithFilteredFetchesEnabled verifies that
// `entire resume` performs a full fetch (no --filter=blob:none) of the
// metadata branch, even when filtered_fetches is enabled in settings.
//
// Filtered fetches are designed for push-time sync where only tree structure
// is needed. Resume requires blob content (transcripts, metadata JSON) and
// must bypass the filter. Without this, the transcript blob would be missing
// locally and resume would fail or fall back to a secondary fetch.
//
// The test verifies:
//   - The metadata branch blob (transcript) is available locally after resume,
//     without relying on FetchingTree's on-demand blob fallback.
//   - The resume output contains "Restored session", confirming the session
//     data was read successfully.
func TestResume_FullFetchEvenWithFilteredFetchesEnabled(t *testing.T) {
	t.Parallel()
	env := NewFeatureBranchEnv(t)

	bareDir := env.SetupBareRemote()

	// Create session, checkpoint, and commit
	checkpointID := createCheckpointedCommit(t, env, "Build auth module", "auth.go", "package auth", "Build auth module")

	// Push user branch + checkpoint branch to remote
	env.GitPush("origin", "HEAD")
	env.RunPrePush("origin")

	if !env.BranchExistsOnRemote(bareDir, paths.MetadataBranchName) {
		t.Fatal("checkpoint branch should exist on remote after push")
	}

	// Clone into a fresh repo (no local metadata branch)
	cloneEnv := env.CloneFrom(bareDir)

	// Enable filtered fetches — this makes remote.Fetch append --filter=blob:none
	// for push-time sync. Resume should bypass this.
	cloneEnv.PatchSettings(map[string]any{
		"strategy_options": map[string]any{
			"filtered_fetches": true,
		},
	})

	if cloneEnv.BranchExists(paths.MetadataBranchName) {
		t.Fatal("metadata branch should not exist locally before resume")
	}

	// Run resume — should perform a full (unfiltered) fetch and restore the session.
	output, err := cloneEnv.RunCLIWithError("resume", "--force", "feature/test-branch")
	t.Logf("resume output: %s", output)

	if err != nil {
		t.Fatalf("resume should succeed with filtered_fetches enabled: %v\nOutput: %s", err, output)
	}

	if !strings.Contains(output, "Restored session") {
		t.Errorf("resume output should contain 'Restored session', got:\n%s", output)
	}

	// Verify the transcript blob is locally available — a filtered fetch would
	// leave only tree objects, making cat-file fail for the blob.
	transcriptPath := SessionFilePath(checkpointID, paths.TranscriptFileName)
	if !cloneEnv.FileExistsInBranch(paths.MetadataBranchName, transcriptPath) {
		t.Fatalf("transcript blob should be locally available after resume (not a partial clone); path: %s", transcriptPath)
	}
}

// =============================================================================
// Helpers
// =============================================================================

// fileExistsOnRemoteBranch checks if a file exists in the metadata branch tree on a bare remote.
func fileExistsOnRemoteBranch(t *testing.T, bareDir, filePath string) bool {
	t.Helper()

	cmd := exec.CommandContext(t.Context(), "git", "cat-file", "-t", paths.MetadataBranchName+":"+filePath)
	cmd.Dir = bareDir
	cmd.Env = testutil.GitIsolatedEnv()
	return cmd.Run() == nil
}

// getRemoteBranchHash returns the commit hash of a branch on a bare remote.
func getRemoteBranchHash(t *testing.T, bareDir, branchName string) string {
	t.Helper()

	cmd := exec.CommandContext(t.Context(), "git", "rev-parse", "refs/heads/"+branchName)
	cmd.Dir = bareDir
	cmd.Env = testutil.GitIsolatedEnv()
	output, err := cmd.Output()
	if err != nil {
		t.Fatalf("failed to get hash for %s on remote: %v", branchName, err)
	}
	return strings.TrimSpace(string(output))
}

// listCheckpointsInDir reads checkpoint IDs from the metadata branch tree.
// This intentionally uses a separate implementation (git ls-tree) rather than
// the production ListCheckpoints() to avoid testing the code with itself.
// The sharded directory structure is documented in CLAUDE.md.
func listCheckpointsInDir(t *testing.T, repoDir string) []string {
	t.Helper()

	cmd := exec.CommandContext(t.Context(), "git", "ls-tree", "-r", "--name-only", paths.MetadataBranchName)
	cmd.Dir = repoDir
	cmd.Env = testutil.GitIsolatedEnv()
	output, err := cmd.Output()
	if err != nil {
		t.Logf("ls-tree failed (branch may not exist): %v", err)
		return nil
	}

	// Parse the sharded structure: <prefix>/<suffix>/metadata.json
	seen := make(map[string]bool)
	var ids []string
	for _, line := range strings.Split(strings.TrimSpace(string(output)), "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		parts := strings.Split(line, "/")
		// Match <prefix>/<suffix>/metadata.json (top-level, not session-level)
		if len(parts) == 3 && parts[2] == paths.MetadataFileName {
			cpID := parts[0] + parts[1]
			if !seen[cpID] {
				seen[cpID] = true
				ids = append(ids, cpID)
			}
		}
	}

	return ids
}

